"""Время и дата голосом: «который час», «какой сегодня день».

Отдельный модуль по той же причине, что остальная логика колонки: чистый
код, проверяется без колонки, без сети и без модели.

Зачем он нужен. «Который час» - самый частый вопрос к часам, и раньше он
уходил в языковую модель, которая отвечала правдоподобно и неправильно:
модель не знает, который час, она знает, как звучит ответ. Часы, которые
врут о времени, - это не часы.

Разбор идёт в тех же словах, в которых говорит человек: «который час»,
«сколько времени», «какое сегодня число», «какой сегодня день», «что за
день». Время отвечаем словами, а не цифрами: «семь тридцать» на часах в
три часа ночи не разбудит так, как «половина четвёртого».

Проверки: python3 vendor/irene-va/jane_when.py
"""

import datetime
import re

# Вопросы о времени суток.
_HOUR_Q = ("который час", "который сейчас час", "сколько времени",
           "что за час", "сейчас сколько", "сколько щас",
           "скажи время", "какое время", "время сейчас",
           # Пробелы были в разборе, а это самая естественная формулировка:
           # «который час» колонка знала, «сколько сейчас времени» - нет.
           "сколько сейчас времени", "сейчас какое время",
           "сейчас которое", "какое сейчас время", "время какое")
# Вопросы о дате и дне.
# Важно: сюда обязаны попадать ВСЕ вопросы из _DAY_Q, потому что проверка дня
# лежит внутри проверки даты. Раньше «какой день недели» было написано только
# в _DAY_Q, из-за чего вопрос не доходил до своей ветки вообще, уходил в
# модель, а модель отвечала «не могу дать информацию о дате» - колонка
# сообщала, что не знает число, зная его.
_DATE_Q = ("какое сегодня число", "какое число", "какой сегодня день",
           "какой сегодня день недели", "что за день", "какое число сегодня",
           "сегодня какое число", "какой день сегодня", "сегодня какой день",
           "какая сегодня дата", "какая дата", "какая у нас дата",
           "что за дата", "какой сейчас день", "какой сейчас дата",
           "какой день недели", "что за день недели", "сегодня дата",
           "какой сегодня число", "какая у нас число")
_DAY_Q = ("какой сегодня день недели", "какой день недели", "что за день недели",
          "какой сегодня день", "что за день")

_WEEKDAY_FULL = ("понедельник", "вторник", "среда", "четверг", "пятница",
                 "суббота", "воскресенье")
_WEEKDAY_SHORT = ("пн", "вт", "ср", "чт", "пт", "сб", "вс")
_WEEKDAY_GEN = ("понедельника", "вторника", "среды", "четверга", "пятницы",
                "субботы", "воскресенья")
_MONTH_GEN = ("января", "февраля", "марта", "апреля", "мая", "июня", "июля",
              "августа", "сентября", "октября", "ноября", "декабря")

# Час в родительном падеже - для «половина четвёртого», «без пяти пятого».
# Раньше на каждую форму была своя функция с собственным словарём, и они
# разошлись; одна таблица не может разойтись сама.
_ORD = {1: "первого", 2: "второго", 3: "третьего", 4: "четвертого",
        5: "пятого", 6: "шестого", 7: "седьмого", 8: "восьмого",
        9: "девятого", 10: "десятого", 11: "одиннадцатого"}

# День месяца словами для даты. «Сегодня 4 октября» синтезатор прочитает
# как «четыре октября», и вслух это уже не то, что человек ожидает;
# сказать «четвёртое октября» - как и говорят.
_DAY_ORD = {
    1: "первое", 2: "второе", 3: "третье", 4: "четвёртое", 5: "пятое",
    6: "шестое", 7: "седьмое", 8: "восьмое", 9: "девятое", 10: "десятое",
    11: "одиннадцатое", 12: "двенадцатое", 13: "тринадцатое",
    14: "четырнадцатое", 15: "пятнадцатое", 16: "шестнадцатое",
    17: "семнадцатое", 18: "восемнадцатое", 19: "девятнадцатое",
    20: "двадцатое", 21: "двадцать первое", 22: "двадцать второе",
    23: "двадцать третье", 24: "двадцать четвёртое", 25: "двадцать пятое",
    26: "двадцать шестое", 27: "двадцать седьмое", 28: "двадцать восьмое",
    29: "двадцать девятое", 30: "тридцатое", 31: "тридцать первое",
}


def year_words(y):
    """«две тысячи двадцать шестой».

    «2026 год» синтезатор произносит как «две тысячи двадцать шесть», но год
    требует родительного падежа: «двадцать шестой». Первая версия этой
    функции путала разряды и на 2026 выдавала «две тысячи 26», то есть год
    буквально проглатывался. Поэтому разряды считаются явно.
    """
    if 2000 <= y <= 2100:
        rest = y - 2000
        if rest == 0:
            return "двухтысячный"
        # Десятки в родительном падеже тянут за собой основу: двадцать ->
        # двадцати. По «двадцат» + «шести» получалось «двадцатшести» - одно
        # слитное слово вместо двух.
        tens = {10: "десяти", 20: "двадцати", 30: "тридцати", 40: "сорока",
                50: "пятидесяти", 60: "шестидесяти", 70: "семидесяти",
                80: "восьмидесяти", 90: "девяноста"}
        ones = {1: "одного", 2: "двух", 3: "трёх", 4: "четырёх",
                5: "пяти", 6: "шести", 7: "семи", 8: "восьми",
                9: "девяти"}
        if rest < 10:
            tail = ones[rest]
        elif rest % 10 == 0:
            tail = tens[rest]
        else:
            tail = tens[rest - rest % 10] + " " + ones[rest % 10]
        return "две тысячи %s" % tail
    return str(y)

# Числительные до двенадцати: часы всегда отвечаем словами.
_NUM = {0: "ноль", 1: "один час", 2: "два часа", 3: "три часа",
        4: "четыре часа", 5: "пять часов", 6: "шесть часов",
        7: "семь часов", 8: "восемь часов", 9: "девять часов",
        10: "десять часов", 11: "одиннадцать часов", 12: "двенадцать часов"}
_MIN = {0: "", 1: "одна минута", 2: "две минуты", 3: "три минуты",
        4: "четыре минуты", 5: "пять минут", 6: "шесть минут",
        7: "семь минут", 8: "восемь минут", 9: "девять минут",
        10: "десять минут", 11: "одиннадцать минут",
        12: "двенадцать минут", 13: "тринадцать минут",
        14: "четырнадцать минут", 15: "пятнадцать минут",
        16: "шестнадцать минут", 17: "семнадцать минут",
        18: "восемнадцать минут", 19: "девятнадцать минут",
        20: "двадцать минут", 30: "полчаса", 40: "сорок минут",
        50: "пятьдесят минут"}


_MIN_WORDS = (
    "ноль", "одна", "две", "три", "четыре", "пять", "шесть", "семь",
    "восемь", "девять", "десять", "одиннадцать", "двенадцать",
    "тринадцать", "четырнадцать", "пятнадцать", "шестнадцать",
    "семнадцать", "восемнадцать", "девятнадцать", "двадцать",
    "двадцать одна", "двадцать две", "двадцать три", "двадцать четыре",
    "двадцать пять", "двадцать шесть", "двадцать семь", "двадцать восемь",
    "двадцать девять", "тридцать", "тридцать одна", "тридцать две",
    "тридцать три", "тридцать четыре", "тридцать пять", "тридцать шесть",
    "тридцать семь", "тридцать восемь", "тридцать девять", "сорок",
    "сорок одна", "сорок две", "сорок три", "сорок четыре", "сорок пять",
    "сорок шесть", "сорок семь", "сорок восемь", "сорок девять",
    "пятьдесят", "пятьдесят одна", "пятьдесят две", "пятьдесят три",
    "пятьдесят четыре", "пятьдесят пять", "пятьдесят шесть",
    "пятьдесят семь", "пятьдесят восемь", "пятьдесят девять",
)


def minute_words(n):
    """«21 минута», «35 минут», «52 минуты».

    Раньше таблица _MIN покрывала только 0-20 и круглые, а на остальное
    подставлялось число: колонка говорила «десять часов и 21 минут». Часы -
    то, где это особенно заметно.
    """
    n = int(n)
    if n in _MIN:
        return _MIN[n]
    return "%s %s" % (_MIN_WORDS[n], _num(n, "минута", "минуты", "минут"))


def _clean(text):
    return " ".join(str(text or "").lower().replace("ё", "е").split())


def is_hour_question(text):
    p = _clean(text)
    return any(p.startswith(q) or (" " + q) in p for q in _HOUR_Q)


def is_date_question(text):
    p = _clean(text)
    return any(q in p for q in _DATE_Q)


def _num(n, table, one, few, many):
    n = int(n)
    if n % 10 == 1 and n % 100 != 11:
        return one
    if 2 <= n % 10 <= 4 and not 12 <= n % 100 <= 14:
        return few
    return many


def speak_hour(dt):
    """«семь тридцать», «половина четвёртого», «ровно семь»."""
    h = dt.hour
    m = dt.minute
    # Полночь и полдень вслух так и называются. «Сейчас ровно ноль часов» -
    # это не ответ часов, а отказ работать.
    if m == 0 and h == 0:
        return "Сейчас ровно полночь."
    if m == 0 and h == 12:
        return "Сейчас ровно полдень."
    if h == 0:
        # После полуночи «ноль часов и пять минут» звучит как отчёт.
        return "Сейчас %s после полуночи." % minute_words(m)
    if m == 0:
        return "Сейчас ровно %s." % _hour(h)
    # «половина четвёртого» и «без пяти» звучат естественно только до
    # полудня; в полдень и ночью по-русски так не говорят, и там лучше
    # обычная форма, чем «без пяти часа».
    if m == 30 and 1 <= h <= 10:
        # Именно следующий: в половине восьмого наступил восьмой час.
        return "Сейчас половина %s." % _ORD[h + 1]
    if m == 15 and 1 <= h <= 10:
        return "Сейчас четверть %s." % _ORD[h + 1]
    if m == 45 and 1 <= h <= 11:
        return "Сейчас без пяти %s." % _next_hour(h)
    if m in _MIN:
        return "Сейчас %s и %s." % (_hour(h), _MIN[m])
    return "Сейчас %s и %s." % (_hour(h), minute_words(m))


# После полудня тоже словами: «одиннадцать часов» звучит естественнее
# «11 часов», а часы - это то, где говорить надо красиво.
_NUM2 = {13: "час", 14: "два часа", 15: "три часа", 16: "четыре часа",
         17: "пять часов", 18: "шесть часов", 19: "семь часов",
         20: "восемь часов", 21: "девять часов", 22: "десять часов",
         23: "одиннадцать часов"}


def _hour(h):
    """Именительный: «семь часов», «час», «одиннадцать часов»."""
    if h == 0:
        return "ноль часов"
    if 1 <= h <= 12:
        return _NUM[h]
    return _NUM2[h]


def _next_hour(h):
    """Следующий час словами в родительном: «без пяти четвертого».

    До 11 утра: в 11:45 по-русски уже не говорят «без пяти двенадцатого»,
    да и таблица на двенадцатом часе обрывается.
    """
    return _ORD[h + 1] if 1 <= h <= 10 else ""


def _num(n, one, few, many):
    n = int(n)
    if n % 10 == 1 and n % 100 != 11:
        return one
    if 2 <= n % 10 <= 4 and not 12 <= n % 100 <= 14:
        return few
    return many


def speak_date(dt):
    """«Сегодня пятница, третье октября»."""
    return "Сегодня %s, %s %s." % (_WEEKDAY_FULL[dt.weekday()],
                                  _DAY_ORD.get(dt.day, str(dt.day)),
                                  _MONTH_GEN[dt.month - 1])


def speak_weekday(dt):
    return "Сегодня %s." % _WEEKDAY_FULL[dt.weekday()]


# Год тоже спрашивают, и раньше на него отвечала модель.
_YEAR_Q = ("какой сейчас год", "какой год", "какой сегодня год",
           "сколько лет", "какой у нас год", "какой это год")
_DATE_WORDS = ("ноль", "одна", "два", "три", "четыре", "пять", "шесть",
               "семь", "восемь", "девять", "однако")


def is_year_question(text):
    p = _clean(text)
    return any(q in p for q in _YEAR_Q)


def speak_year(dt):
    """«Сейчас две тысячи двадцать шестой год.»"""
    return "Сейчас %s год." % year_words(dt.year)


def answer(text, now=None):
    """Ответ на вопрос о времени и дате. None - это не про них."""
    if is_hour_question(text):
        return speak_hour(now or datetime.datetime.now())
    if is_year_question(text):
        return speak_year(now or datetime.datetime.now())
    if is_date_question(text):
        p = _clean(text)
        if any(q in p for q in _DAY_Q):
            return speak_weekday(now or datetime.datetime.now())
        return speak_date(now or datetime.datetime.now())
    return None


# ---------------------------------------------------------------------------
# Проверки
# ---------------------------------------------------------------------------
def selfcheck():
    fails = []

    def want(cond, msg):
        if not cond:
            fails.append(msg)

    # Каждый вопрос про дату обязан уметь ответить сам. Формулировка, которая
    # не покрыта, уходит в модель, а модель на дату отвечает отказом.
    for q in ("какая сегодня дата", "какая дата", "какой день недели",
              "какое сегодня число", "какой сегодня день", "какой год"):
        got = answer(q)
        want(got is not None, "дата без ответа: %s" % q)
        want(got is not None and not re.search(r"[A-Za-z]", got),
             "в ответе про дату английские буквы: %r" % got)

    def at(h, m=0, d=2, mon=10):
        return datetime.datetime(2026, mon, d, h, m)

    # Вопросы распознаются.
    for q in ("который час", "Который сейчас час?", "сколько времени",
              "какое время", "скажи время"):
        want(is_hour_question(q), "не узнан вопрос о времени: %s" % q)
    for q in ("какое сегодня число", "какой сегодня день",
              "какой сегодня день недели", "что за день"):
        want(is_date_question(q), "не узнан вопрос о дате: %s" % q)

    # И отвечает на них.
    want(answer("который час", at(7, 30)) == "Сейчас половина восьмого.",
         "половина восьмого: %r" % answer("который час", at(7, 30)))
    want(answer("сколько времени", at(7, 0)) == "Сейчас ровно семь часов.",
         "ровно семь: %r" % answer("сколько времени", at(7, 0)))
    want(answer("который час", at(3, 15)) == "Сейчас четверть четвертого.",
         "четверть: %r" % answer("который час", at(3, 15)))
    want(answer("который час", at(3, 45)) == "Сейчас без пяти четвертого.",
         "без пяти: %r" % answer("который час", at(3, 45)))
    want(answer("который час", at(23, 5)) ==
         "Сейчас одиннадцать часов и пять минут.",
         "полночь: %r" % answer("который час", at(23, 5)))
    # Полночь вслух называют полночью. «Сейчас ровно ноль часов» - это не
    # ответ часов, а отказ работать.
    want(answer("который час", at(0, 0)) == "Сейчас ровно полночь.",
         "полночь: %r" % answer("который час", at(0, 0)))
    want("полдень" in answer("который час", at(12, 0)),
         "полдень: %r" % answer("который час", at(12, 0)))
    want("после полуночи" in answer("который час", at(0, 5)),
         "после полуночи: %r" % answer("который час", at(0, 5)))
    want(answer("который час", at(13, 7)) == "Сейчас час и семь минут.",
         "после полудня: %r" % answer("который час", at(13, 7)))
    want(answer("который час", at(15, 12)) ==
         "Сейчас три часа и двенадцать минут.",
         "минуты словами: %r" % answer("который час", at(15, 12)))

    # Дата: 2 октября 2026 - пятница.
    # День месяца словами: «4 октября» синтезатор прочитает как «четыре
    # октября», а вслух говорят «четвёртое октября».
    want(answer("какое сегодня число", at(12, 0)) ==
         "Сегодня пятница, второе октября.",
         "дата: %r" % answer("какое сегодня число", at(12, 0)))
    want(answer("какой сегодня день", at(12, 0)) == "Сегодня пятница.",
         "день недели: %r" % answer("какой сегодня день", at(12, 0)))

    # Цифры в ответе о времени - это не мелочь. Раньше таблица минут
    # покрывала только 0-20 и круглые, и на «21 минута» колонка говорила
    # «десять часов и 21 минут»: цифра и неверное окончание в одной фразе.
    for m, want_tail in ((21, "двадцать одна минута"),
                        (35, "тридцать пять минут"),
                        (52, "пятьдесят две минуты"),
                        (59, "пятьдесят девять минут"),
                        (11, "одиннадцать минут"),
                        (44, "сорок четыре минуты")):
        got = answer("который час", at(10, m))
        want(want_tail in got, "%d минут: %r" % (m, got))
        want(not re.search(r"\d", got or ""),
             "в ответе о времени есть цифры: %r" % got)

    # «сколько сейчас времени» - самая естественная формулировка, и её не
    # было в разборе, хотя «который час» знала.
    for q in ("сколько сейчас времени", "сейчас какое время",
              "какое сейчас время"):
        want(answer(q, at(10, 21)) is not None,
             "«%s» не понято" % q)

    # Год спрашивают, и раньше на него отвечала модель.
    want(answer("какой сейчас год", at(10, 21)) ==
         "Сейчас две тысячи двадцати шести год.",
         "год: %r" % answer("какой сейчас год", at(10, 21)))
    # Год словами и раздельно: «двадцатшести» и «две тысячи 26» -
    # это либо одно слитное слово, либо год, проглоченный целиком.
    for y, want_words in ((2005, "две тысячи пяти"),
                           (2011, "две тысячи десяти одного"),
                           (2026, "две тысячи двадцати шести"),
                           (2035, "две тысячи тридцати пяти")):
        got = year_words(y)
        want(got == want_words, "год %d: %r, ожидалось %r"
             % (y, got, want_words))
        want(" " in got.split("тысячи ")[-1] or got.endswith("пяти"),
             "год %d склеен без пробела: %r" % (y, got))
    want(answer("сколько лет", at(10, 21)) is not None, "«сколько лет» не понято")

    # Чужой разговор не должен ловиться.
    for q in ("какая сейчас погода", "включи свет", "буди меня в 7 утра",
              "поставь таймер на пять минут"):
        want(answer(q, at(12, 0)) is None, "лишнее сработало на: %s" % q)

    # Ни одна минута не должна падать и ни одна не должна остаться цифрой.
    for h in range(24):
        for m in range(60):
            got = speak_hour(at(h, m))
            want(bool(got) and got.endswith("."),
                 "часы не сказаны для %02d:%02d: %r" % (h, m, got))
            want(not re.search(r"\d", got or ""),
                 "цифры в часах для %02d:%02d: %r" % (h, m, got))

    for f in fails:
        print("FAIL  " + f)
    if not fails:
        print("ok    jane_when: часы отвечают временем, а не правдоподобием")
    print("ИТОГ: провалено %d" % len(fails))
    return 1 if fails else 0


if __name__ == "__main__":
    import sys
    sys.exit(selfcheck())